1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Neon Solar Implosion</title>
7	<style>
8	  html, body { margin: 0; height: 100%; background: #020008; overflow: hidden; }
9	  canvas { display: block; width: 100vw; height: 100vh; }
10	</style>
11	<script type="importmap">
12	{ "imports": {
13	  "three": "https://cdn.jsdelivr.net/npm/<email>/build/three.module.js",
14	  "three/addons/": "https://cdn.jsdelivr.net/npm/<email>/examples/jsm/"
15	} }
16	</script>
17	</head>
18	<body>
19	<script type="module">
20	import * as THREE from 'three';
21	import { EffectComposer } from 'three/addons/postprocessing/EffectComposer.js';
22	import { RenderPass } from 'three/addons/postprocessing/RenderPass.js';
23	import { UnrealBloomPass } from 'three/addons/postprocessing/UnrealBloomPass.js';
24	import { ShaderPass } from 'three/addons/postprocessing/ShaderPass.js';
25	import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
26	
27	/*
28	  10-second loop, every motion is a pure function of t in [0,10):
29	   0.0 - 3.0  neon solar system in orbit
30	   3.0 - 6.0  gravitational implosion: everything spirals into the sun
31	   6.0        singularity flash + shockwave
32	   6.0 - 9.8  nova rebirth: particles burst out, overshoot, settle on their orbits
33	  Orbital phases are made loop-exact by folding the leftover angle into the implosion swirl.
34	*/
35	const LOOP = 10, TAU = Math.PI * 2;
36	const params = new URLSearchParams(location.search);
37	const frozenT = params.has('t') ? parseFloat(params.get('t')) : null;
38	
39	// ---------- renderer / scene ----------
40	const renderer = new THREE.WebGLRenderer({ antialias: false, powerPreference: 'high-performance' });
41	renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
42	renderer.setSize(innerWidth, innerHeight);
43	renderer.setClearColor(0x020008, 1);
44	renderer.toneMapping = THREE.ACESFilmicToneMapping;
45	renderer.toneMappingExposure = 1.05;
46	document.body.appendChild(renderer.domElement);
47	
48	const scene = new THREE.Scene();
49	const camera = new THREE.PerspectiveCamera(50, innerWidth / innerHeight, 0.1, 2000);
50	
51	// ---------- deterministic random ----------
52	let seed = 1337;
53	const rnd = () => { seed = (seed * 16807) % 2147483647; return (seed - 1) / 2147483646; };
54	const gauss = () => Math.sqrt(-2 * Math.log(rnd() + 1e-9)) * Math.cos(TAU * rnd());
55	const unit = () => { const z = rnd() * 2 - 1, a = rnd() * TAU, s = Math.sqrt(1 - z * z); return [s * Math.cos(a), z, s * Math.sin(a)]; };
56	const col = h => { const c = new THREE.Color(h); return [c.r, c.g, c.b]; };
57	const mixc = (a, b, k) => [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k];
58	
59	// ---------- particle buffers ----------
60	const A = { orbit: [], local: [], dir: [], color: [], misc: [], tilt: [] };
61	let count = 0;
62	const angSpeed = r => r <= 0 ? 0 : 1.15 * Math.pow(6 / r, 1.5);
63	// Extra rotation that closes the loop: total angle over 10 s becomes an exact number of turns.
64	function closure(r, w) {
65	  if (r <= 0) return 0;
66	  const extraTurns = Math.round(THREE.MathUtils.clamp(14 / r, 1, 3));
67	  return TAU * (Math.ceil(w * LOOP / TAU) + extraTurns) - w * LOOP;
68	}
69	function add(o) {
70	  const w = angSpeed(o.r);
71	  A.orbit.push(o.r, o.a0, w, closure(o.r, w));
72	  A.local.push(...o.local);
73	  A.dir.push(...unit());
74	  A.color.push(...o.color);
75	  const delay = THREE.MathUtils.clamp(1 - o.r / 44, 0, 1) * 0.75 + rnd() * 0.25;
76	  A.misc.push(o.size, rnd(), delay, o.kind);
77	  A.tilt.push(o.incl || 0, o.node || 0, o.spin || 0);
78	  count++;
79	}
80	
81	// Sun: boiling particle sphere + corona
82	const sunCols = [col('#fff36b'), col('#ffb000'), col('#ff4d00'), col('#ff1f8f')];
83	for (let i = 0; i < 26000; i++) {
84	  const d = unit(), rr = 3.0 * Math.pow(rnd(), 0.25);
85	  const k = rr / 3.0;
86	  const c = k < 0.7 ? mixc(sunCols[0], sunCols[1], k / 0.7) : k < 0.92 ? mixc(sunCols[1], sunCols[2], (k - 0.7) / 0.22) : mixc(sunCols[2], sunCols[3], (k - 0.92) / 0.08);
87	  add({ r: 0, a0: 0, local: [d[0] * rr, d[1] * rr, d[2] * rr], color: c, size: 0.16, kind: 0, spin: 1 });
88	}
89	for (let i = 0; i < 9000; i++) {
90	  const d = unit(), rr = 3.0 + Math.abs(gauss()) * 1.4;
91	  const c = mixc(col('#ff2bd6'), col('#7a2bff'), Math.min(1, (rr - 3) / 3));
92	  add({ r: 0, a0: 0, local: [d[0] * rr, d[1] * rr, d[2] * rr], color: c, size: 0.12, kind: 0, spin: -1 });
93	}
94	
95	// Planets
96	const planets = [
97	  { r: 6.0,  R: 0.35, n: 2200,  cols: ['#ff4fd8', '#ff9df0'], spin: 4, incl: 0.06 },
98	  { r: 8.6,  R: 0.6,  n: 4000,  cols: ['#ffb347', '#ff5ec4'], spin: 2, incl: 0.03 },
99	  { r: 11.2, R: 0.65, n: 5000,  cols: ['#00e5ff', '#39ff88', '#2979ff'], spin: 5, incl: 0.0, moon: true },
100	  { r: 13.8, R: 0.45, n: 3000,  cols: ['#ff3355', '#ff7a1a'], spin: 5, incl: 0.035 },
101	  { r: 22.5, R: 1.7,  n: 13000, cols: ['#ffd000', '#ff6a00', '#ff2fa0', '#ffe9a0'], spin: 6, incl: 0.02, bands: true },
102	  { r: 29.0, R: 1.3,  n: 8000,  cols: ['#f6ff6b', '#ffae00', '#ff7ad9'], spin: 6, incl: 0.04, bands: true, ring: true },
103	  { r: 35.0, R: 0.95, n: 5000,  cols: ['#00ffd5', '#7dfcff'], spin: 4, incl: 0.015 },
104	  { r: 40.5, R: 0.95, n: 5000,  cols: ['#4d5bff', '#a64dff', '#00b3ff'], spin: 4, incl: 0.03 },
105	];
106	for (const p of planets) {
107	  const a0 = rnd() * TAU, node = rnd() * TAU, cols = p.cols.map(col);
108	  for (let i = 0; i < p.n; i++) {
109	    const d = unit(), rr = p.R * Math.pow(rnd(), 0.18);
110	    let c;
111	    if (p.bands) { const b = 0.5 + 0.5 * Math.sin(d[1] * 11 + Math.sin(d[0] * 3) * 0.6); c = mixc(cols[0], cols[1 + (i % (cols.length - 1))], b); }
112	    else c = mixc(cols[0], cols[1 + (i % (cols.length - 1))], rnd());
113	    add({ r: p.r, a0, local: [d[0] * rr, d[1] * rr, d[2] * rr], color: c, size: 0.13, kind: 1, incl: p.incl, node, spin: p.spin });
114	  }
115	  // atmosphere halo
116	  for (let i = 0; i < p.n * 0.25; i++) {
117	    const d = unit(), rr = p.R * (1.05 + Math.abs(gauss()) * 0.25);
118	    add({ r: p.r, a0, local: [d[0] * rr, d[1] * rr, d[2] * rr], color: mixc(cols[0], [1, 1, 1], 0.2), size: 0.09, kind: 1, incl: p.incl, node, spin: p.spin });
119	  }
120	  if (p.ring) {
121	    const tiltR = 0.45;
122	    for (let i = 0; i < 12000; i++) {
123	      const a = rnd() * TAU, rr = p.R * (1.5 + rnd() * 1.3);
124	      const gap = rr > p.R * 2.2 && rr < p.R * 2.32; if (gap) continue;
125	      let x = Math.cos(a) * rr, y = gauss() * 0.02, z = Math.sin(a) * rr;
126	      const y2 = y * Math.cos(tiltR) - x * Math.sin(tiltR), x2 = y * Math.sin(tiltR) + x * Math.cos(tiltR);
127	      const c = mixc(col('#b388ff'), col('#00e5ff'), (rr / p.R - 1.5) / 1.3);
128	      add({ r: p.r, a0, local: [x2, y2, z], color: c, size: 0.08, kind: 1, incl: p.incl, node, spin: 1 });
129	    }
130	  }
131	  if (p.moon) {
132	    for (let i = 0; i < 700; i++) {
133	      const d = unit(), rr = 0.2 * Math.pow(rnd(), 0.2);
134	      add({ r: p.r, a0, local: [1.6 + d[0] * rr, d[1] * rr, d[2] * rr], color: col('#e8f6ff'), size: 0.1, kind: 1, incl: p.incl, node, spin: 3 });
135	    }
136	  }
137	  // neon orbit trail
138	  for (let i = 0; i < 3200; i++) {
139	    const c = mixc(cols[0], col('#ffffff'), 0.1);
140	    add({ r: p.r + gauss() * 0.06, a0: rnd() * TAU, local: [0, gauss() * 0.04, 0], color: c, size: 0.07, kind: 2, incl: p.incl, node });
141	  }
142	}
143	// Asteroid belt
144	for (let i = 0; i < 16000; i++) {
145	  const r = 16.5 + rnd() * 3.2 + gauss() * 0.3;
146	  const c = mixc(col('#8a7dff'), col('#ff4fd8'), rnd());
147	  add({ r, a0: rnd() * TAU, local: [0, gauss() * 0.25, 0], color: c, size: 0.09 + rnd() * 0.05, kind: 3, incl: 0.02, node: 1.0 });
148	}
149	// Kuiper dust
150	for (let i = 0; i < 9000; i++) {
151	  const r = 45 + rnd() * 10;
152	  add({ r, a0: rnd() * TAU, local: [0, gauss() * 0.8, 0], color: mixc(col('#00e5ff'), col('#5b2bff'), rnd()), size: 0.1, kind: 3, incl: 0.03, node: 2.0 });
153	}
154	
155	// ---------- shared shader code ----------
156	const common = /* glsl */`
157	  uniform float uTime;
158	  uniform float uProj;
159	  attribute vec4 aOrbit; attribute vec3 aLocal; attribute vec3 aDir;
160	  attribute vec3 aColor; attribute vec4 aMisc; attribute vec3 aTilt;
161	  const float TAU = 6.28318530718; const float PI = 3.14159265359; const float LOOP = 10.0;
162	  float smoother(float x){ x = clamp(x,0.,1.); return x*x*x*(x*(x*6.-15.)+10.); }
163	  mat3 rotY(float a){ float c=cos(a), s=sin(a); return mat3(c,0.,-s, 0.,1.,0., s,0.,c); }
164	  mat3 rotX(float a){ float c=cos(a), s=sin(a); return mat3(1.,0.,0., 0.,c,s, 0.,-s,c); }
165	
166	  // position of this particle at loop time t; heat 0..1, phase 0 = implosion side, 1 = rebirth side
167	  vec3 sysPos(float t, out float heat, out float side){
168	    float r = aOrbit.x, a0 = aOrbit.y, w = aOrbit.z, R = aOrbit.w;
169	    float delay = aMisc.z, kind = aMisc.w;
170	    float s = smoother((t - 3.0 - delay*0.9) / 5.7);
171	    float ang = a0 + w*t + R*s;
172	
173	    float tStart = 3.0 + delay*1.5;
174	    float ti = clamp((t - tStart) / (6.0 - tStart), 0., 1.);
175	    float c = ti*ti*ti;
176	    float u = clamp((t - 6.0) / (3.0 + delay*0.8), 0., 1.);
177	    float f, scatter = 0.;
178	    if (t < 6.0) { f = 1.0 - c; heat = c; side = 0.; }
179	    else { float v = 1.0 - u; f = 1.0 - v*v*v*cos(3.0*PI*u); heat = v*v*v; side = 1.; scatter = pow(sin(PI*u), 2.0); }
180	
181	    vec3 center = vec3(cos(ang)*r, 0., sin(ang)*r);
182	    center = rotY(aTilt.y) * (rotX(aTilt.x) * (rotY(-aTilt.y) * center));
183	
184	    float spin = aTilt.z * TAU * t / LOOP + TAU * 2.0 * s;
185	    vec3 loc = rotY(spin) * aLocal;
186	    if (kind < 0.5) { // boiling sun surface, periodic in t
187	      float ph = TAU * t / LOOP;
188	      float b = sin(dot(aLocal, vec3(2.1,1.7,1.3)) + ph*3.0) * sin(dot(aLocal, vec3(-1.3,2.4,0.7)) - ph*2.0);
189	      loc *= 1.0 + 0.09*b;
190	    }
191	    vec3 p = center + loc;
192	    float tw = c*(1.0-c)*4.0;
193	    p.y += sin(ang*3.0 + aMisc.y*TAU) * tw * (r*0.10 + 0.6);
194	    p *= f;
195	    p += aDir * (0.9 * pow(heat, 6.0));            // finite-size singularity core
196	    p += aDir * scatter * (r*0.32 + 4.0);           // nova burst shell
197	    return p;
198	  }
199	  vec3 heatColor(float heat, float side){
200	    float h4 = heat*heat*heat*heat;
201	    vec3 hotIn  = mix(vec3(1.0,0.1,0.7), vec3(1.0,0.9,1.0), h4);
202	    vec3 hotOut = mix(vec3(0.15,0.8,1.0), vec3(0.95,0.9,1.0), h4);
203	    vec3 hot = mix(hotIn, hotOut, side);
204	    return mix(aColor, hot, smoothstep(0.0, 0.9, heat) * 0.85);
205	  }
206	`;
207	
208	const geo = new THREE.BufferGeometry();
209	const f32 = a => new Float32Array(a);
210	geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(count * 3), 3));
211	geo.setAttribute('aOrbit', new THREE.BufferAttribute(f32(A.orbit), 4));
212	geo.setAttribute('aLocal', new THREE.BufferAttribute(f32(A.local), 3));
213	geo.setAttribute('aDir', new THREE.BufferAttribute(f32(A.dir), 3));
214	geo.setAttribute('aColor', new THREE.BufferAttribute(f32(A.color), 3));
215	geo.setAttribute('aMisc', new THREE.BufferAttribute(f32(A.misc), 4));
216	geo.setAttribute('aTilt', new THREE.BufferAttribute(f32(A.tilt), 3));
217	geo.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 500);
218	
219	const uniforms = { uTime: { value: 0 }, uProj: { value: 1 }, uFlash: { value: 0 } };
220	
221	const pointsMat = new THREE.ShaderMaterial({
222	  uniforms,
223	  vertexShader: common + /* glsl */`
224	    varying vec3 vColor; varying float vAlpha;
225	    void main(){
226	      float heat, side;
227	      vec3 p = sysPos(uTime, heat, side);
228	      vec4 mv = modelViewMatrix * vec4(p, 1.0);
229	      gl_Position = projectionMatrix * mv;
230	      float kind = aMisc.w;
231	      float size = aMisc.x * (1.0 + heat*0.6);
232	      gl_PointSize = clamp(size * uProj / -mv.z, 1.0, 64.0);
233	      vColor = heatColor(heat, side);
234	      float base = kind < 0.5 ? 0.09 : kind < 1.5 ? 0.065 : kind < 2.5 ? 0.30 : 0.32;
235	      float tw = 0.75 + 0.25*sin(aMisc.y*80.0 + TAU*uTime*2.0/LOOP*(1.0+floor(aMisc.y*3.0)));
236	      float cool = 1.0 - heat; vAlpha = base * tw * (cool*cool*0.97 + 0.012);
237	    }`,
238	  fragmentShader: /* glsl */`
239	    varying vec3 vColor; varying float vAlpha;
240	    void main(){
241	      float d = length(gl_PointCoord - 0.5);
242	      float a = 1.0 - smoothstep(0.0, 0.5, d); a *= a;
243	      gl_FragColor = vec4(vColor * a * vAlpha, 1.0);
244	    }`,
245	  transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
246	});
247	scene.add(new THREE.Points(geo, pointsMat));
248	
249	// ---------- motion streaks: line segments from p(t-dt) to p(t) ----------
250	{
251	  const pick = [];
252	  const misc = A.misc;
253	  for (let i = 0; i < count; i++) if (misc[i * 4 + 3] > 0.5 && rnd() < 0.22) pick.push(i);
254	  const n = pick.length * 2;
255	  const lg = new THREE.BufferGeometry();
256	  const names = { aOrbit: 4, aLocal: 3, aDir: 3, aColor: 3, aMisc: 4, aTilt: 3 };
257	  const src = { aOrbit: A.orbit, aLocal: A.local, aDir: A.dir, aColor: A.color, aMisc: A.misc, aTilt: A.tilt };
258	  for (const [name, sz] of Object.entries(names)) {
259	    const out = new Float32Array(n * sz);
260	    pick.forEach((idx, j) => { for (let e = 0; e < 2; e++) for (let k = 0; k < sz; k++) out[(j * 2 + e) * sz + k] = src[name][idx * sz + k]; });
261	    lg.setAttribute(name, new THREE.BufferAttribute(out, sz));
262	  }
263	  const tail = new Float32Array(n); for (let j = 0; j < pick.length; j++) tail[j * 2 + 1] = 1;
264	  lg.setAttribute('aTail', new THREE.BufferAttribute(tail, 1));
265	  lg.setAttribute('position', new THREE.BufferAttribute(new Float32Array(n * 3), 3));
266	  lg.boundingSphere = new THREE.Sphere(new THREE.Vector3(), 500);
267	  const lineMat = new THREE.ShaderMaterial({
268	    uniforms,
269	    vertexShader: common + /* glsl */`
270	      attribute float aTail;
271	      varying vec3 vColor; varying float vAlpha;
272	      void main(){
273	        float h0, s0, h1, s1;
274	        vec3 p0 = sysPos(uTime, h0, s0);
275	        vec3 p1 = sysPos(mod(uTime - 0.07 + LOOP, LOOP), h1, s1);
276	        vec3 p = mix(p0, p1, aTail);
277	        gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
278	        float speed = length(p0 - p1) / 0.07;
279	        vColor = heatColor(h0, s0);
280	        vAlpha = clamp((speed - 4.0) * 0.002, 0.0, 0.07) * (aMisc.w < 1.5 ? 0.25 : 1.0) * (1.0 - h0*0.8) * (1.0 - aTail * 0.9);
281	      }`,
282	    fragmentShader: /* glsl */`
283	      varying vec3 vColor; varying float vAlpha;
284	      void main(){ gl_FragColor = vec4(vColor * vAlpha, 1.0); }`,
285	    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
286	  });
287	  scene.add(new THREE.LineSegments(lg, lineMat));
288	}
289	
290	// ---------- background stars ----------
291	{
292	  const n = 7000, pos = new Float32Array(n * 3), c = new Float32Array(n * 3), r = new Float32Array(n);
293	  const pal = ['#ffffff', '#9fdcff', '#ff9df0', '#c3a6ff', '#7dfcff'].map(col);
294	  for (let i = 0; i < n; i++) {
295	    const d = unit(), R = 260 + rnd() * 300;
296	    pos.set([d[0] * R, d[1] * R, d[2] * R], i * 3);
297	    c.set(pal[i % pal.length], i * 3); r[i] = rnd();
298	  }
299	  const g = new THREE.BufferGeometry();
300	  g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
301	  g.setAttribute('aColor', new THREE.BufferAttribute(c, 3));
302	  g.setAttribute('aRand', new THREE.BufferAttribute(r, 1));
303	  const m = new THREE.ShaderMaterial({
304	    uniforms,
305	    vertexShader: /* glsl */`
306	      uniform float uTime, uProj, uFlash; attribute vec3 aColor; attribute float aRand;
307	      varying vec3 vColor; varying float vA;
308	      void main(){
309	        vec3 p = position * (1.0 - 0.06*uFlash);
310	        vec4 mv = modelViewMatrix * vec4(p, 1.0);
311	        gl_Position = projectionMatrix * mv;
312	        gl_PointSize = max(1.0, (0.6 + aRand*1.2) * uProj / -mv.z);
313	        vColor = aColor;
314	        vA = (0.25 + 0.35*aRand) * (0.7 + 0.3*sin(aRand*200.0 + 6.2831853*uTime*(1.0+floor(aRand*3.0))/10.0)) + uFlash*0.4;
315	      }`,
316	    fragmentShader: /* glsl */`
317	      varying vec3 vColor; varying float vA;
318	      void main(){ float d = length(gl_PointCoord-0.5); float a = 1.0 - smoothstep(0.0,0.5,d); gl_FragColor = vec4(vColor*a*a*vA,1.0); }`,
319	    transparent: true, depthWrite: false, blending: THREE.AdditiveBlending,
320	  });
321	  scene.add(new THREE.Points(g, m));
322	}
323	
324	// ---------- billboard glow: sun halo + singularity flash with anamorphic streak ----------
325	const glowU = { uSun: { value: 1 }, uFlash: uniforms.uFlash, uAspect: { value: 1 } };
326	const glow = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), new THREE.ShaderMaterial({
327	  uniforms: glowU,
328	  vertexShader: /* glsl */`
329	    varying vec2 vP;
330	    void main(){
331	      vP = position.xy;
332	      vec4 mv = viewMatrix * vec4(0.0,0.0,0.0,1.0);
333	      mv.xy += position.xy * 34.0;
334	      gl_Position = projectionMatrix * mv;
335	    }`,
336	  fragmentShader: /* glsl */`
337	    uniform float uSun, uFlash; varying vec2 vP;
338	    void main(){
339	      float r = length(vP);
340	      float halo = exp(-r*16.0) * 0.35 + exp(-r*6.0) * 0.03;
341	      vec3 sun = vec3(1.0,0.45,0.15) * halo * uSun + vec3(1.0,0.1,0.6) * exp(-r*8.0) * 0.04 * uSun;
342	      float core = exp(-r*14.0) * 1.6 + exp(-r*5.0) * 0.12;
343	      float streak = exp(-abs(vP.y)*120.0) * exp(-abs(vP.x)*2.5) * 0.9;
344	      float streakV = exp(-abs(vP.x)*140.0) * exp(-abs(vP.y)*4.0) * 0.5;
345	      vec3 flash = (vec3(1.0,0.9,1.0)*core + vec3(0.25,0.8,1.0)*streak + vec3(1.0,0.3,0.9)*streakV) * uFlash;
346	      vec3 c = sun + flash;
347	      gl_FragColor = vec4(c * (1.0 - smoothstep(0.7, 1.0, r)), 1.0);
348	    }`,
349	  transparent: true, depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending,
350	}));
351	glow.frustumCulled = false; glow.renderOrder = 10;
352	scene.add(glow);
353	
354	// ---------- shockwave rings in the ecliptic ----------
355	const shockU = { uShock: { value: -1 } };
356	const shock = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), new THREE.ShaderMaterial({
357	  uniforms: shockU,
