s = s[:start] + """// ---------- billboard glow: sun core/corona + singularity (point core, anamorphic streak, rays) ----------
const glowU = { uSun: { value: 1 }, uFlash: uniforms.uFlash, uPre: { value: 0 }, uRel: { value: 0 }, uPhase: { value: 0 } };
const glow = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), new THREE.ShaderMaterial({
  uniforms: glowU,
  vertexShader: /* glsl */`
    varying vec2 vP;
    void main(){
      vP = position.xy;
      vec4 mv = viewMatrix * vec4(0.0,0.0,0.0,1.0);
      mv.xy += position.xy * 34.0;
      gl_Position = projectionMatrix * mv;
    }`,
  fragmentShader: /* glsl */`
    uniform float uSun, uFlash, uPre, uRel, uPhase; varying vec2 vP;
    void main(){
      float r = length(vP), th = atan(vP.y, vP.x);
      // sun: hot yellow core -> orange -> magenta corona with slow periodic streamers (sun radius ~ 0.088)
      float core = exp(-pow(r/0.05, 2.0));
      float stream = 0.75 + 0.25*sin(th*7.0 + uPhase) * sin(th*3.0 - 2.0*uPhase);
      float cor = exp(-max(r - 0.08, 0.0) * 30.0 / stream) * smoothstep(0.03, 0.09, r);
      vec3 sun = vec3(1.0,0.62,0.05)*core*0.35 + mix(vec3(1.0,0.25,0.0), vec3(1.0,0.0,0.55), smoothstep(0.08,0.16,r))*cor*0.22
               + vec3(0.6,0.0,1.0)*exp(-r*7.0)*0.025;
      sun *= uSun;
      // anticipation: tight point brightens while a thin ring contracts onto it
      float rr = 0.22*(1.0 - uPre);
      float pre = exp(-pow(r/0.006, 2.0)) * 3.0 * uPre
                + exp(-pow((r - rr)/0.0035, 2.0)) * uPre * (1.0 - uPre) * 4.0;
      vec3 preC = vec3(1.0,0.15,0.75) * pre;
      // flash: tiny white-hot point, razor anamorphic streak, radial light rays that run outward on release
      float pt = exp(-pow(r/0.012, 2.0)) * 14.0 + exp(-r*45.0) * 1.2;
      float ax = abs(vP.x), ay = abs(vP.y);
      float streak = exp(-ay/0.0022) * exp(-ax*1.6) * 5.0 + exp(-ay/0.012) * exp(-ax*3.0) * 0.5;
      float streakV = exp(-ax/0.0018) * exp(-ay*9.0) * 1.2;
      float L = 0.08 + uRel*1.1;
      float rays = pow(abs(cos(th*6.0 + 0.3)), 90.0) + 0.7*pow(abs(cos(th*11.0 + 1.1)), 160.0) + 0.5*pow(abs(cos(th*17.0 + 2.0)), 220.0);
      rays *= exp(-r/L) * smoothstep(0.0, 0.02, r) * 1.6;
      vec3 flash = (vec3(1.0,0.95,1.0)*pt + vec3(0.1,0.75,1.0)*streak + vec3(1.0,0.2,0.85)*streakV + mix(vec3(1.0,0.1,0.8), vec3(0.2,0.5,1.0), smoothstep(0.0,0.3,r))*rays) * uFlash;
      vec3 c = sun + preC + flash;
      gl_FragColor = vec4(c * (1.0 - smoothstep(0.7, 1.0, r)), 1.0);
    }`,
  transparent: true, depthWrite: false, depthTest: false, blending: THREE.AdditiveBlending,
}));
""" + s[end:]

rep("""const bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), 0.9, 0.45, 0.12);
composer.addPass(bloom);
composer.addPass(new OutputPass());
const finish = new ShaderPass({
  uniforms: { tDiffuse: { value: null }, uAb: { value: 0 }, uTime: { value: 0 } },""","""const bloom = new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), 0.7, 0.35, 0.28);
composer.addPass(bloom);
// final grade: chromatic aberration, hue-preserving tonemap (scale by max channel, so saturated neon never
// drifts to white), saturation lift, white only allowed via uWhite (the 6 s flash peak), sRGB encode, vignette, grain
const finish = new ShaderPass({
  uniforms: { tDiffuse: { value: null }, uAb: { value: 0 }, uTime: { value: 0 }, uWhite: { value: 0 }, uExpo: { value: 1.25 } },""")
rep("""    uniform sampler2D tDiffuse; uniform float uAb, uTime; varying vec2 vUv;
    float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898,78.233)) + uTime*13.7) * 43758.5453); }
    void main(){
      vec2 d = vUv - 0.5;
      float k = 0.0025 + uAb * 0.012;
      vec3 c;
      c.r = texture2D(tDiffuse, vUv + d*k).r;
      c.g = texture2D(tDiffuse, vUv).g;
      c.b = texture2D(tDiffuse, vUv - d*k).b;
      float vig = 1.0 - smoothstep(0.25, 0.95, length(d*vec2(1.15,1.0)));
      c *= mix(0.55, 1.0, vig);
      c += (hash(vUv*1000.0) - 0.5) * 0.025;
      gl_FragColor = vec4(c, 1.0);
    }`,""","""    uniform sampler2D tDiffuse; uniform float uAb, uTime, uWhite, uExpo; varying vec2 vUv;
    float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898,78.233)) + floor(mod(uTime, 10.0)*30.0)*1.37) * 43758.5453); }
    vec3 toSRGB(vec3 c){ c = clamp(c, 0.0, 1.0); return mix(c*12.92, 1.055*pow(c, vec3(1.0/2.4)) - 0.055, step(0.0031308, c)); }
    void main(){
      vec2 d = vUv - 0.5;
      float k = 0.0025 + uAb * 0.012;
      vec3 c;
      c.r = texture2D(tDiffuse, vUv + d*k).r;
      c.g = texture2D(tDiffuse, vUv).g;
      c.b = texture2D(tDiffuse, vUv - d*k).b;
      c = max(c * uExpo, 0.0);
      // saturation lift in linear light (keeps blacks black)
      float l = dot(c, vec3(0.2126,0.7152,0.0722));
      c = max(mix(vec3(l), c, 1.22), 0.0);
      float m = max(max(c.r, c.g), c.b);
      float mt = m * (1.0 + m/16.0) / (1.0 + m);            // extended Reinhard on the max channel
      vec3 hue = c * (mt / max(m, 1e-5));
      c = mix(hue, vec3(mt), uWhite * smoothstep(0.8, 6.0, m));
      c = toSRGB(c);
      float vig = 1.0 - smoothstep(0.3, 0.95, length(d*vec2(1.15,1.0)));
      c *= mix(0.5, 1.0, vig);
      c += (hash(vUv*1000.0) - 0.5) * 0.014;
      gl_FragColor = vec4(c, 1.0);
    }`,""")
# timeline
rep("""function flashAt(t) {
  if (t < 6) return Math.pow(smoother((t - 4.8) / 1.2), 6) * 0.7;
  return Math.exp(-(t - 6) * 2.6);
}""","""function flashAt(t) {           // short: ignites in the last 40 ms, decays within ~0.5 s
  if (t < 6) return Math.pow(smoother((t - 5.96) / 0.04), 2);
  return Math.exp(-(t - 6) * 5.5);
}
const preAt = t => (t < 6 ? smoother((t - 5.45) / 0.5) : 0);   // anticipation: contraction + dimming""")
rep("""  const fl = flashAt(t);
  uniforms.uFlash.value = fl;""","""  const fl = flashAt(t), pre = preAt(t);
  uniforms.uFlash.value = fl;
  uniforms.uDim.value = 1 - 0.6 * pre * (1 - fl);
  glowU.uPre.value = pre * (1 - fl);
  glowU.uRel.value = t >= 6 ? Math.min(1, (t - 6) / 0.8) : 0;
  glowU.uPhase.value = TAU * t / LOOP;""")
rep("""  const dist = (74 - 30 * env) * Math.pow""","""  const dist = (74 - 30 * env) * (1 - 0.05 * pre) * Math.pow""")
rep("""  bloom.strength = 0.85 + 0.5 * fl + 0.15 * env;
  bloom.radius = 0.45 + 0.2 * fl;
  finish.uniforms.uAb.value = fl + env * 0.3;""","""  bloom.strength = 0.7 + 0.35 * fl + 0.1 * env;
  bloom.radius = 0.35 + 0.15 * fl;
  finish.uniforms.uAb.value = fl * 0.6 + env * 0.3;
  finish.uniforms.uWhite.value = Math.min(1, fl * 1.2);""")
open(p,'w').write(s)
